/**
 * Per-account MFA contract.
 *
 *  - The second factor is bound to the ACCOUNT: a code generated from one
 *    user's secret must not verify another user's session.
 *  - Enrollment is password-gated and does not count as verified until a code
 *    from the new secret is presented.
 *  - A code is single-use (RFC 6238 §5.2) and the ledger is the shared
 *    users.mfa_last_step column, so a replay is refused by a second API
 *    instance that never saw the first use.
 *
 * Codes are generated by an independent RFC 4226 implementation in this file,
 * anchored to the published RFC 6238 vector, so the test cannot pass by
 * sharing a defect with server/totp.js.
 */
import 'dotenv/config';
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createHmac } from 'node:crypto';

const PERIOD_SECONDS = 30;
const DIGITS = 6;
const DEMO_PASSWORD = 'Clinician123';
const ADMIN_PASSWORD = 'Admin123';

// Policy for this test process only (node --test runs each file separately).
// The legacy shared secret must NOT be needed to enforce MFA any more.
process.env.MFA_REQUIRED = 'true';
delete process.env.MFA_TOTP_SECRET;

const { default: app } = await import('../server/app.js');
const { default: secondWorker } = await import('../server/app.js?worker=2');
const { closePool, query } = await import('../server/db.js');

const BASE32 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';

const decodeBase32 = (input) => {
  let bits = 0;
  let value = 0;
  const output = [];
  for (const char of input.replace(/=+$/, '').toUpperCase()) {
    const index = BASE32.indexOf(char);
    assert.notEqual(index, -1, `unexpected base32 character ${char}`);
    value = (value << 5) | index;
    bits += 5;
    if (bits >= 8) {
      output.push((value >>> (bits - 8)) & 0xff);
      bits -= 8;
    }
  }
  return Buffer.from(output);
};

/** RFC 4226 HOTP, 6 digits: the TOTP value for one 30-second step. */
const hotp = (key, counter) => {
  const message = Buffer.alloc(8);
  message.writeUInt32BE(Math.floor(counter / 2 ** 32), 0);
  message.writeUInt32BE(counter % 2 ** 32, 4);
  const digest = createHmac('sha1', key).update(message).digest();
  const offset = digest[digest.length - 1] & 0x0f;
  const binary =
    ((digest[offset] & 0x7f) << 24) |
    ((digest[offset + 1] & 0xff) << 16) |
    ((digest[offset + 2] & 0xff) << 8) |
    (digest[offset + 3] & 0xff);
  return String(binary % 10 ** DIGITS).padStart(DIGITS, '0');
};

const currentStep = () => Math.floor(Date.now() / 1000 / PERIOD_SECONDS);
const codeFor = (secret, step = currentStep()) => hotp(decodeBase32(secret), step);

let server;
let secondServer;
let base;
let secondBase;
const sessions = new Map();

const listen = async (target) => {
  const httpServer = target.listen(0, '127.0.0.1');
  await new Promise((resolve, reject) => {
    httpServer.once('listening', resolve);
    httpServer.once('error', reject);
  });
  return httpServer;
};

const loginOn = async (root, username, password) => {
  const response = await fetch(`${root}/api/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ username, password }),
  });
  assert.equal(response.status, 200, `${username} must sign in`);
  const raw = response.headers.getSetCookie?.()[0] ?? response.headers.get('set-cookie');
  return raw.split(';')[0];
};

const post = (root, path, cookie, body) =>
  fetch(`${root}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', cookie },
    body: JSON.stringify(body ?? {}),
  });

/** Signs in and returns { cookie, password } for an account. */
const signIn = async (username, password) => {
  if (!sessions.has(username)) {
    const cookie = await loginOn(base, username, password);
    sessions.set(username, { cookie, password });
  }
  return sessions.get(username);
};

/** Enrolls the account and returns its base32 secret. */
const enroll = async (username, password) => {
  const session = await signIn(username, password);
  const response = await post(base, '/api/mfa/enroll', session.cookie, { currentPassword: password });
  assert.equal(response.status, 201, `${username} must be able to enroll`);
  const body = await response.json();
  assert.match(body.secret, /^[A-Z2-7]{16,}$/, 'enrollment returns a base32 secret');
  assert.ok(body.otpauthUrl.startsWith('otpauth://totp/'), 'enrollment returns a provisioning URI');
  return body.secret;
};

before(async () => {
  server = await listen(app);
  secondServer = await listen(secondWorker);
  base = `http://127.0.0.1:${server.address().port}`;
  secondBase = `http://127.0.0.1:${secondServer.address().port}`;
});

after(async () => {
  await query(
    `UPDATE users SET mfa_secret = NULL, mfa_enrolled_at = NULL, mfa_last_step = NULL
      WHERE username IN ('clinician.demo', 'clinician.martin', 'clinician.rivera', 'admin')`
  );
  await new Promise((resolve) => server.close(resolve));
  await new Promise((resolve) => secondServer.close(resolve));
  await closePool();
});

test('the independent generator matches the RFC 6238 test vector', () => {
  // RFC 6238 SHA-1 secret for "12345678901234567890", T=59s, 6 digits.
  assert.equal(codeFor('GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ', 1), '287082');
});

test('an unenrolled session is refused while MFA is required', async () => {
  const session = await signIn('clinician.demo', DEMO_PASSWORD);
  const before = await fetch(`${base}/api/bootstrap`, { headers: { cookie: session.cookie } });
  assert.equal(before.status, 403);
  assert.equal((await before.json()).code, 'MFA_ENROLLMENT_REQUIRED');

  // Enrollment needs the current password, so a stolen session cannot attach
  // its own device to the account.
  const refused = await post(base, '/api/mfa/enroll', session.cookie, { currentPassword: 'wrong-password' });
  assert.equal(refused.status, 401);
});

test('a code is accepted once and refused on replay', async () => {
  const secret = await enroll('clinician.demo', DEMO_PASSWORD);
  const session = await signIn('clinician.demo', DEMO_PASSWORD);
  const code = codeFor(secret);

  const first = await post(base, '/api/mfa/verify', session.cookie, { code });
  assert.equal(first.status, 200, 'a fresh code must verify');

  const replay = await post(base, '/api/mfa/verify', session.cookie, { code });
  assert.equal(replay.status, 401, 'the same code must not verify twice');
  assert.equal((await replay.json()).code, 'MFA_CODE_REUSED');

  const status = await fetch(`${base}/api/mfa/status`, { headers: { cookie: session.cookie } });
  const state = await status.json();
  assert.equal(state.required, true);
  assert.equal(state.enrolled, true, 'the first successful code confirms the enrollment');
});

test('a replayed code is refused by a second API instance (shared ledger)', async () => {
  const secret = await enroll('clinician.martin', DEMO_PASSWORD);
  const cookie = (await signIn('clinician.martin', DEMO_PASSWORD)).cookie;
  const code = codeFor(secret);

  const first = await post(base, '/api/mfa/verify', cookie, { code });
  assert.equal(first.status, 200, 'the first worker accepts the code');

  const replay = await post(secondBase, '/api/mfa/verify', cookie, { code });
  assert.equal(replay.status, 401, 'a second worker must refuse the same code');
  assert.equal((await replay.json()).code, 'MFA_CODE_REUSED');
});

test("one account's code does not verify another account", async () => {
  const adminSecret = await enroll('admin', ADMIN_PASSWORD);
  const adminCookie = (await signIn('admin', ADMIN_PASSWORD)).cookie;
  assert.equal((await post(base, '/api/mfa/verify', adminCookie, { code: codeFor(adminSecret) })).status, 200);

  // Rivera never enrolled: a code from the admin's authenticator must not
  // stand in for a second factor on Rivera's session.
  const rivera = await signIn('clinician.rivera', DEMO_PASSWORD);
  const crossed = await post(base, '/api/mfa/verify', rivera.cookie, { code: codeFor(adminSecret, currentStep()) });
  assert.equal(crossed.status, 409, 'an account with no enrolled authenticator cannot verify');
  assert.equal((await crossed.json()).code, 'MFA_NOT_ENROLLED');
});

test('an adjacent-step code within the drift window still verifies', async () => {
  const secret = await enroll('admin', ADMIN_PASSWORD);
  const cookie = (await signIn('admin', ADMIN_PASSWORD)).cookie;

  // The previous step is still inside the ±1 window and nothing newer has been
  // consumed for this account, so it must be accepted (no over-blocking).
  const previous = await post(base, '/api/mfa/verify', cookie, { code: codeFor(secret, currentStep() - 1) });
  assert.equal(previous.status, 200);

  const current = await post(base, '/api/mfa/verify', cookie, { code: codeFor(secret, currentStep()) });
  assert.equal(current.status, 200, 'a newer step after an older one is still accepted');
});
